export type HydraApiOperationId = keyof typeof HYDRA_API_OPERATIONS;

export function hydraApiPath(operationId: HydraApiOperationId, parameters: Record<string,string|number> = {}): string {
  let path: string = HYDRA_API_OPERATIONS[operationId].path;
  for (const [key,value] of Object.entries(parameters)) path = path.replace(`{${key}}`, encodeURIComponent(String(value)));
  return path;
}

export async function hydraApiRequest(operationId: HydraApiOperationId, parameters: Record<string,string|number> = {}, init: RequestInit = {}): Promise<Response> {
  const operation = HYDRA_API_OPERATIONS[operationId];
  return backendFetch(hydraApiPath(operationId, parameters), { ...init, method: init.method ?? operation.method });
}
